/// Support shared by every record in this schema: the text rendering, the
/// checksum, and reading records out of a file.
///
/// These are the same operation for every type, so they live here once and
/// the generated records forward to them. Keeping the file entry points in
/// one module is also what makes `std::fs` a single dependency rather than
/// one per record, should a consumer need to gate it out.
#[allow(dead_code)]
pub mod blit_runtime {
    use std::fmt;

    /// CRC32C (Castagnoli), bitwise over a byte slice.
    pub fn crc32c(data: &[u8]) -> u32 {
        let mut c: u32 = 0xffffffff;
        for &byte in data {
            c ^= byte as u32;
            for _ in 0..8 {
                let mask = if (c & 1) != 0 { 0xffffffff } else { 0 };
                c = (c >> 1) ^ (0x82f63b78 & mask);
            }
        }
        c ^ 0xffffffff
    }

    /// The bytes of any record in this schema, without copying them.
    ///
    /// # Safety
    ///
    /// `T` must be one of the generated `#[repr(C)]` records: fixed-size,
    /// pointer-free, and with every padding byte an explicit field, which
    /// is what makes reading it as bytes well defined.
    pub unsafe fn as_bytes<T>(item: &T) -> &[u8] {
        std::slice::from_raw_parts(item as *const T as *const u8, std::mem::size_of::<T>())
    }

    /// Reinterprets a slice as a record, without copying it.
    ///
    /// `None` when the slice is too short or is not aligned for `T`: a
    /// reference to a misaligned `T` is undefined behaviour, so it is
    /// refused rather than produced.
    ///
    /// # Safety
    ///
    /// As `as_bytes`: `T` must be one of the generated records, for which
    /// every bit pattern of the right length is a valid value.
    pub unsafe fn from_bytes<T>(bytes: &[u8]) -> Option<&T> {
        if bytes.len() < std::mem::size_of::<T>() {
            return None;
        }
        let pointer = bytes.as_ptr();
        if (pointer as usize) % std::mem::align_of::<T>() != 0 {
            return None;
        }
        Some(&*(pointer as *const T))
    }

    /// Copies a record out of a slice at any alignment.
    ///
    /// # Safety
    ///
    /// As `from_bytes`.
    pub unsafe fn copy_from_bytes<T>(bytes: &[u8]) -> Option<T> {
        if bytes.len() < std::mem::size_of::<T>() {
            return None;
        }
        let mut item = std::mem::MaybeUninit::<T>::uninit();
        std::ptr::copy_nonoverlapping(
            bytes.as_ptr(),
            item.as_mut_ptr() as *mut u8,
            std::mem::size_of::<T>(),
        );
        Some(item.assume_init())
    }

    /// Reads exactly one record. A file whose length is not exactly one
    /// record is a file that disagrees with this schema, so it is rejected
    /// rather than read.
    ///
    /// # Safety
    ///
    /// As `as_bytes`: `T` must be one of the generated records, for which
    /// every bit pattern of the right length is a valid value.
    pub unsafe fn read_file<P: AsRef<std::path::Path>, T>(path: P) -> std::io::Result<T> {
        let bytes = std::fs::read(path)?;
        if bytes.len() != std::mem::size_of::<T>() {
            return Err(std::io::Error::new(
                std::io::ErrorKind::InvalidData,
                "File size does not equal struct size",
            ));
        }
        let mut item = std::mem::MaybeUninit::<T>::uninit();
        std::ptr::copy_nonoverlapping(
            bytes.as_ptr(),
            item.as_mut_ptr() as *mut u8,
            std::mem::size_of::<T>(),
        );
        Ok(item.assume_init())
    }

    /// Reads a whole file of back-to-back records.
    ///
    /// # Safety
    ///
    /// As `read_file`.
    pub unsafe fn read_array_file<P: AsRef<std::path::Path>, T>(
        path: P,
    ) -> std::io::Result<Vec<T>> {
        let bytes = std::fs::read(path)?;
        let elem_size = std::mem::size_of::<T>();
        if bytes.len() % elem_size != 0 {
            return Err(std::io::Error::new(
                std::io::ErrorKind::InvalidData,
                "File size is not a multiple of struct size",
            ));
        }
        let count = bytes.len() / elem_size;
        let mut items: Vec<T> = Vec::with_capacity(count);
        std::ptr::copy_nonoverlapping(
            bytes.as_ptr(),
            items.as_mut_ptr() as *mut u8,
            count * elem_size,
        );
        items.set_len(count);
        Ok(items)
    }

    /// A `fmt::Write` over a fixed byte buffer.
    ///
    /// Writing past the end truncates rather than failing, and `needed`
    /// keeps counting, so one pass reports both what was written and what a
    /// complete rendering would have taken.
    pub struct SliceSink<'a> {
        dest: &'a mut [u8],
        written: usize,
        needed: usize,
    }

    impl<'a> SliceSink<'a> {
        pub fn new(dest: &'a mut [u8]) -> SliceSink<'a> {
            SliceSink {
                dest,
                written: 0,
                needed: 0,
            }
        }

        /// Bytes placed in the buffer.
        pub fn written(&self) -> usize {
            self.written
        }

        /// Bytes a complete rendering would take. Greater than `written`
        /// exactly when the text was truncated.
        pub fn needed(&self) -> usize {
            self.needed
        }
    }

    impl fmt::Write for SliceSink<'_> {
        fn write_str(&mut self, text: &str) -> fmt::Result {
            let bytes = text.as_bytes();
            self.needed += bytes.len();
            let room = self.dest.len() - self.written;
            let mut take = if bytes.len() < room {
                bytes.len()
            } else {
                room
            };
            // Never split a code point: the buffer stays valid UTF-8 even
            // when it fills mid-character.
            while take > 0 && !text.is_char_boundary(take) {
                take -= 1;
            }
            self.dest[self.written..self.written + take].copy_from_slice(&bytes[..take]);
            self.written += take;
            Ok(())
        }
    }

    pub fn write_bool(out: &mut dyn fmt::Write, value: bool) -> fmt::Result {
        out.write_str(if value { "true" } else { "false" })
    }

    /// Rust's `Display` for floats is already the shortest decimal that
    /// round-trips; only the names of the non-finite values are restated,
    /// so every language in this schema prints them the same way.
    pub fn write_f32(out: &mut dyn fmt::Write, value: f32) -> fmt::Result {
        if value.is_nan() {
            return out.write_str("nan");
        }
        if value.is_infinite() {
            return out.write_str(if value < 0.0 { "-inf" } else { "inf" });
        }
        write!(out, "{}", value)
    }

    pub fn write_f64(out: &mut dyn fmt::Write, value: f64) -> fmt::Result {
        if value.is_nan() {
            return out.write_str("nan");
        }
        if value.is_infinite() {
            return out.write_str(if value < 0.0 { "-inf" } else { "inf" });
        }
        write!(out, "{}", value)
    }

    /// Opaque bytes: every byte, in order, as lowercase hex.
    pub fn write_hex(out: &mut dyn fmt::Write, data: &[u8]) -> fmt::Result {
        const DIGITS: &[u8; 16] = b"0123456789abcdef";
        out.write_str("0x")?;
        for &byte in data {
            let pair = [DIGITS[(byte >> 4) as usize], DIGITS[(byte & 0x0f) as usize]];
            out.write_str(std::str::from_utf8(&pair).map_err(|_| fmt::Error)?)?;
        }
        Ok(())
    }

    /// Fixed-length text: a NUL ends the string and the bytes after it are
    /// not data. Content that is valid UTF-8 is written through unchanged;
    /// bytes that are not are escaped rather than lost, so a mislabelled
    /// field still prints something faithful to the record.
    pub fn write_text(out: &mut dyn fmt::Write, data: &[u8]) -> fmt::Result {
        let end = data
            .iter()
            .position(|&byte| byte == 0)
            .unwrap_or(data.len());
        let mut rest = &data[..end];
        out.write_str("\"")?;
        loop {
            match std::str::from_utf8(rest) {
                Ok(text) => {
                    write_escaped(out, text)?;
                    break;
                }
                Err(error) => {
                    let good = error.valid_up_to();
                    write_escaped(
                        out,
                        std::str::from_utf8(&rest[..good]).map_err(|_| fmt::Error)?,
                    )?;
                    let skipped = error.error_len().unwrap_or(rest.len() - good);
                    for &byte in &rest[good..good + skipped] {
                        write!(out, "\\x{:02x}", byte)?;
                    }
                    rest = &rest[good + skipped..];
                }
            }
        }
        out.write_str("\"")
    }

    /// Writes `text` with the quote, the backslash, and the C0 controls
    /// escaped, in runs, so ordinary content costs one write per string
    /// rather than one per character.
    fn write_escaped(out: &mut dyn fmt::Write, text: &str) -> fmt::Result {
        let mut flushed = 0;
        for (index, character) in text.char_indices() {
            let escape = match character {
                '"' => "\\\"",
                '\\' => "\\\\",
                '\n' => "\\n",
                '\r' => "\\r",
                '\t' => "\\t",
                other if (other as u32) < 0x20 || (other as u32) == 0x7f => {
                    out.write_str(&text[flushed..index])?;
                    write!(out, "\\x{:02x}", other as u32)?;
                    flushed = index + other.len_utf8();
                    continue;
                }
                _ => continue,
            };
            out.write_str(&text[flushed..index])?;
            out.write_str(escape)?;
            flushed = index + character.len_utf8();
        }
        out.write_str(&text[flushed..])
    }

    /// What a session hello or a store's leading frame answers.
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub enum HandshakeVerdict {
        Identical,
        Compatible,
        Breaking,
    }

    /// Grades a peer's binding map against this build's.
    ///
    /// Both maps are ascending by msg_id, so one merge pass decides it. A
    /// shared identifier under two digests is a frame that would decode into
    /// plausible nonsense, and nothing skippable about it: refuse. An
    /// identifier only one side holds is exactly what the frame header's
    /// `block_length` exists for -- a producer's extra type is stepped over,
    /// a consumer's is never sent.
    ///
    /// Here rather than in each container because both containers ask it: a
    /// store is a hello that outlives its writer.
    pub fn handshake_verdict(
        ours_msg_ids: &[u16],
        ours_digests: &[u64],
        theirs_msg_ids: &[u16],
        theirs_digests: &[u64],
    ) -> HandshakeVerdict {
        let mut ours = 0usize;
        let mut theirs = 0usize;
        let mut unshared = false;
        while ours < ours_msg_ids.len() && theirs < theirs_msg_ids.len() {
            if ours_msg_ids[ours] == theirs_msg_ids[theirs] {
                if ours_digests[ours] != theirs_digests[theirs] {
                    return HandshakeVerdict::Breaking;
                }
                ours += 1;
                theirs += 1;
            } else if ours_msg_ids[ours] < theirs_msg_ids[theirs] {
                unshared = true;
                ours += 1;
            } else {
                unshared = true;
                theirs += 1;
            }
        }
        if ours < ours_msg_ids.len() || theirs < theirs_msg_ids.len() {
            unshared = true;
        }
        if unshared {
            HandshakeVerdict::Compatible
        } else {
            HandshakeVerdict::Identical
        }
    }
}

