// Wire-message dispatch (self-identifying frames).
#[repr(transparent)]
#[derive(Debug, Copy, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct MsgId(pub u16);

#[allow(non_upper_case_globals)]
impl MsgId {
    pub const NullMessage: MsgId = MsgId(0);
    pub const Hello: MsgId = MsgId(1);
    pub const ChatLine: MsgId = MsgId(2);
    pub const Chunk: MsgId = MsgId(3);
    pub const Status: MsgId = MsgId(4);
    pub const MakiStatus: MsgId = MsgId(5);
    pub const MakiCommand: MsgId = MsgId(6);
    pub const MakiAck: MsgId = MsgId(7);

    /// The raw wire value.
    pub const fn get(self) -> u16 {
        self.0
    }

    /// The declared name for this id, or `None` when this schema does not
    /// declare it. Useful for logging an id that cannot be dispatched.
    pub fn name(self) -> Option<&'static str> {
        match self {
            MsgId::Hello => Some("Hello"),
            MsgId::ChatLine => Some("ChatLine"),
            MsgId::Chunk => Some("Chunk"),
            MsgId::Status => Some("Status"),
            MsgId::MakiStatus => Some("MakiStatus"),
            MsgId::MakiCommand => Some("MakiCommand"),
            MsgId::MakiAck => Some("MakiAck"),
            _ => None,
        }
    }

    /// True when this schema declares the id.
    pub fn is_declared(self) -> bool {
        self.name().is_some()
    }
}

impl From<u16> for MsgId {
    fn from(value: u16) -> Self {
        MsgId(value)
    }
}

impl From<MsgId> for u16 {
    fn from(value: MsgId) -> Self {
        value.0
    }
}

