/// Fixed frame length for a msg_id, or `None` when unknown to this schema.
pub fn blit_message_size(msg_id: MsgId) -> Option<u32> {
    match msg_id {
        MsgId::Hello => Some(Hello::LENGTH),
        MsgId::ChatLine => Some(ChatLine::LENGTH),
        MsgId::Chunk => Some(Chunk::LENGTH),
        MsgId::Status => Some(Status::LENGTH),
        MsgId::MakiStatus => Some(MakiStatus::LENGTH),
        MsgId::MakiCommand => Some(MakiCommand::LENGTH),
        MsgId::MakiAck => Some(MakiAck::LENGTH),
        _ => None,
    }
}

/// The bytes the format reserves in a framable record: its padding extents
/// as (offset, length) pairs, ascending, embedded records and array-stride
/// gaps included. Empty for an id this schema does not declare -- an unknown
/// record has no layout to hold its bytes to -- and for a type whose fields
/// tile it exactly.
pub fn blit_padding_extents(msg_id: MsgId) -> &'static [(u32, u32)] {
    match msg_id {
        _ => &[],
    }
}

/// True when every format-reserved byte of the body is zero, which
/// Invariant 2 requires of every writer. A store walk asks this of each
/// record under a declared id; padding that holds anything is a record no
/// conforming writer produced.
pub fn blit_validate_padding(msg_id: MsgId, body: &[u8]) -> bool {
    for &(offset, length) in blit_padding_extents(msg_id) {
        match body.get(offset as usize..offset as usize + length as usize) {
            Some(bytes) => {
                if bytes.iter().any(|&byte| byte != 0) {
                    return false;
                }
            }
            None => return false,
        }
    }
    true
}

/// The template id of the frame at the start of `bytes`, without decoding
/// it. Identity lives in the frame header, not in the record.
pub fn blit_peek_msg_id(bytes: &[u8]) -> Option<MsgId> {
    Some(FrameHeader::read(bytes)?.template_id)
}

// Stream framing. A record's own msg_id identifies bytes already in hand;
// block_length is what says where the next record starts, so an
// unrecognized template can be stepped over instead of ending the stream.
#[repr(C)]
#[derive(Debug, Copy, Clone, PartialEq, Eq)]
pub struct FrameHeader {
    pub block_length: u32,
    pub template_id: MsgId,
    pub version: u16,
}

impl FrameHeader {
    pub const LENGTH: usize = 8;

    /// The frame this header describes, header included.
    pub const fn frame_length(&self) -> u64 {
        Self::LENGTH as u64 + self.block_length as u64
    }

    /// The header for a record this schema declares, or `None` for one it
    /// does not. A writer emits this, then the record's bytes.
    pub fn for_msg_id(msg_id: MsgId) -> Option<FrameHeader> {
        Some(FrameHeader {
            block_length: blit_message_size(msg_id)?,
            template_id: msg_id,
            version: BLIT_FRAME_FORMAT_VERSION,
        })
    }

    /// Reads a frame header, or `None` when fewer than LENGTH bytes remain
    /// or the version is not this build's framing format version. The
    /// template_id is not validated: an id this schema does not declare is
    /// exactly the case block_length exists to handle. The version is,
    /// because it is the format's field, not the writer's -- a frame
    /// stamped with another framing version is a chain whose lengths this
    /// reader cannot trust, and stepping onward would be guessing at
    /// boundaries.
    ///
    /// Bytes are gathered explicitly rather than via `try_into`, which is
    /// only in the prelude from the 2021 edition onward; a consumer picks
    /// its own edition, so generated code cannot assume one.
    pub fn read(bytes: &[u8]) -> Option<FrameHeader> {
        if bytes.len() < Self::LENGTH {
            return None;
        }
        if u16::from_le_bytes([bytes[6], bytes[7]]) != BLIT_FRAME_FORMAT_VERSION {
            return None;
        }
        Some(FrameHeader {
            block_length: u32::from_le_bytes([bytes[0], bytes[1], bytes[2], bytes[3]]),
            template_id: MsgId(u16::from_le_bytes([bytes[4], bytes[5]])),
            version: u16::from_le_bytes([bytes[6], bytes[7]]),
        })
    }
}

/// The record's bytes, without the header. `None` when truncated.
pub fn blit_frame_body(bytes: &[u8]) -> Option<&[u8]> {
    let header = FrameHeader::read(bytes)?;
    let end = header.frame_length() as usize;
    bytes.get(FrameHeader::LENGTH..end)
}

/// Everything after this frame. Works without knowing the template, so a
/// consumer can skip a record a newer producer introduced.
pub fn blit_next_frame(bytes: &[u8]) -> Option<&[u8]> {
    let header = FrameHeader::read(bytes)?;
    bytes.get(header.frame_length() as usize..)
}

// The binding map on the wire: the (msg_id, H(T)) pairs of a writer's
// framable set, in the one shape a peer can read without already
// agreeing with the writer about the schema. A session hello carries
// one, and so does a store's leading frame.
//
// The capacity is a format constant, not a function of the schema: a
// schema-sized vector would put the reader back where it started,
// needing the writer's schema to find the end of the writer's map.
pub mod blit_binding_map {
    use super::blit_runtime::{HandshakeVerdict, handshake_verdict};

    pub const LENGTH: usize = 208;
    pub const CAPACITY: usize = 20;
    pub const MSG_ID: u16 = 65535;

    /// This schema's binding map: the (msg_id, H(T)) pairs of its
    /// framable set, ascending by msg_id. What a peer's map is graded
    /// against -- shared identifiers must agree, and one only a
    /// producer holds is skippable.
    ///
    /// Here rather than beside the schema's other constants because it
    /// is the one part of this surface that is not the format's: a
    /// crate holding two schemas has two sets of pairs and one of
    /// everything else.
    pub const OUR_MSG_IDS: &[u16] = &[1, 2, 3, 4, 5, 6, 7];
    /// The digests beside them: each entry's H(T) truncated to eight
    /// bytes, big-endian.
    pub const OUR_DIGESTS: &[u64] = &[
        0xC98EFED71DE06A8C,
        0x793B62817760793D,
        0x27F24AE45CD9D35F,
        0x26F295233E12D355,
        0x1CC36391B98226C1,
        0x00D3ADDABAC37ECC,
        0x576E122290BC9B3C,
    ];

    const COUNT_OFFSET: usize = 0;
    const RESERVED_OFFSET: usize = 4;
    const MSG_IDS_OFFSET: usize = 8;
    const DIGESTS_OFFSET: usize = 48;

    /// Writes this build's map into the first LENGTH bytes of `dest`.
    pub fn write(dest: &mut [u8]) {
        for byte in dest[..LENGTH].iter_mut() {
            *byte = 0;
        }
        let count = OUR_MSG_IDS.len() as u32;
        dest[COUNT_OFFSET..COUNT_OFFSET + 4].copy_from_slice(&count.to_le_bytes());
        for index in 0..OUR_MSG_IDS.len() {
            let at = MSG_IDS_OFFSET + index * 2;
            dest[at..at + 2].copy_from_slice(&OUR_MSG_IDS[index].to_le_bytes());
            let at = DIGESTS_OFFSET + index * 8;
            dest[at..at + 8].copy_from_slice(&OUR_DIGESTS[index].to_le_bytes());
        }
    }

    /// Grades a peer's map against this build's. `None` when the bytes
    /// are not a well-formed map.
    ///
    /// The peer's own fields are checked before they are used: the count
    /// and the ordering are theirs, and the merge is a decision procedure
    /// only if both maps really are ascending.
    pub fn grade(bytes: &[u8]) -> Option<HandshakeVerdict> {
        if bytes.len() < LENGTH {
            return None;
        }
        let claimed = u32::from_le_bytes([
            bytes[COUNT_OFFSET],
            bytes[COUNT_OFFSET + 1],
            bytes[COUNT_OFFSET + 2],
            bytes[COUNT_OFFSET + 3],
        ]) as usize;
        if claimed > CAPACITY {
            return None;
        }
        // The reserved word and the slots past entry_count are the
        // format's: every writer zeroes the record before filling its
        // live entries, so bytes there that hold anything were not
        // written by a conforming writer and the record is not a map.
        if bytes[RESERVED_OFFSET..RESERVED_OFFSET + 4]
            .iter()
            .any(|&byte| byte != 0)
        {
            return None;
        }
        if bytes[MSG_IDS_OFFSET + claimed * 2..MSG_IDS_OFFSET + CAPACITY * 2]
            .iter()
            .any(|&byte| byte != 0)
        {
            return None;
        }
        if bytes[DIGESTS_OFFSET + claimed * 8..DIGESTS_OFFSET + CAPACITY * 8]
            .iter()
            .any(|&byte| byte != 0)
        {
            return None;
        }
        let mut msg_ids = [0u16; CAPACITY];
        let mut digests = [0u64; CAPACITY];
        for index in 0..claimed {
            let at = MSG_IDS_OFFSET + index * 2;
            msg_ids[index] = u16::from_le_bytes([bytes[at], bytes[at + 1]]);
            let at = DIGESTS_OFFSET + index * 8;
            digests[index] = u64::from_le_bytes([
                bytes[at],
                bytes[at + 1],
                bytes[at + 2],
                bytes[at + 3],
                bytes[at + 4],
                bytes[at + 5],
                bytes[at + 6],
                bytes[at + 7],
            ]);
            if index != 0 && msg_ids[index] <= msg_ids[index - 1] {
                return None;
            }
        }
        Some(handshake_verdict(
            OUR_MSG_IDS,
            OUR_DIGESTS,
            &msg_ids[..claimed],
            &digests[..claimed],
        ))
    }
}
